package com.cpf.security.api.audit;
import com.cpf.security.api.crypto.CpfDigitalSignature;import java.time.Instant;import java.util.*;
/** append-only audit hash-chain record. payload 원문 대신 canonical masked payload hash만 보존합니다. */
public record CpfTamperAuditRecord(long sequence,String transactionId,String actor,String action,String payloadHash,String previousHash,String currentHash,CpfDigitalSignature signature,Instant occurredAt){public CpfTamperAuditRecord{if(sequence<1)throw new IllegalArgumentException("sequence must be positive");if(transactionId==null||transactionId.isBlank())throw new IllegalArgumentException("transactionId required");actor=Objects.requireNonNullElse(actor,"");if(action==null||action.isBlank())throw new IllegalArgumentException("action required");if(payloadHash==null||payloadHash.isBlank())throw new IllegalArgumentException("payloadHash required");previousHash=Objects.requireNonNullElse(previousHash,"");if(currentHash==null||currentHash.isBlank())throw new IllegalArgumentException("currentHash required");occurredAt=Objects.requireNonNullElseGet(occurredAt,Instant::now);}}
